#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Configuration. Every path comes from doc/planning/repository-on-the-860-drive.md; each can be overridden by an
# environment variable so a fixture run never touches the real disks.
HOME_DIR="$(readlink -f "${HOME}")"
USER_NAME="$(id -un)"
GROUP_NAME="$(id -gn)"
REPO="${MOVE_REPOSITORY:-${HOME_DIR}/Monochromatic}"
EXTERNAL_WORKTREES="${MOVE_EXTERNAL_WORKTREES:-${HOME_DIR}/worktrees}"
DRIVE="${MOVE_DRIVE:-/var/mnt/encrypted}"
DEST_ROOT="${MOVE_DESTINATION_ROOT:-${DRIVE}/repository}"
RECEIVED="${DEST_ROOT}/received-read-only"
FINAL="${DEST_ROOT}/Monochromatic"
EXTERNAL_FINAL="${DEST_ROOT}/external-worktrees"
SNAPSHOTS="${MOVE_SNAPSHOTS:-${HOME_DIR}/repository-move-snapshots}"
MOVE_STATE="${MOVE_STATE_DIR:-${HOME_DIR}/repository-move-state}"
WIZ="${MOVE_STATE}/wizard"
DANGLING="${MOVE_DANGLING_DIR:-${HOME_DIR}/temp/agent/dangling}"
MOVE_SCRIPT="${DANGLING}/move-repository.ts"
SCAN_SCRIPT="${DANGLING}/list-uncommitted-work.ts"
INVENTORY="${DANGLING}/inventory-nested.txt"
INVENTORY_MAIN="${MOVE_INVENTORY_MAIN:-home/user/Monochromatic}"
FIXTURE_PARENT="${MOVE_FIXTURE_PARENT:-${HOME_DIR}/temp/agent}"
CLI_GIT_STATE="${XDG_STATE_HOME:-${HOME_DIR}/.local/state}/cli-git/service"
DRY_RUN="${WIZARD_DRY_RUN:-0}"

# Numbers. "plan" means the plan text gives the value; "author" means this script's author chose it as a bound so that
# nothing waits forever, and the owner may change it with the named variable.
TRANSFER_DEADLINE="${MOVE_TRANSFER_DEADLINE_SECONDS:-14400}"     # plan, section "Deadlines": 14400 s per transfer
EXTERNAL_RSYNC_DEADLINE="${MOVE_EXTERNAL_DEADLINE_SECONDS:-7200}" # plan, section "The copy": 7200 s per external worktree
MIN_FREE_GIB="${MOVE_MIN_FREE_GIB:-150}"                          # plan, section "Capacity policy": default 150
NVME_MIN_FREE_GIB="${MOVE_NVME_MIN_FREE_GIB:-100}"                # plan, section "Capacity policy": 100
MARGIN_PERCENT=25                                                 # plan, section "Capacity policy": one quarter
SHARING_LIMIT_PERCENT=125                                         # derived from the same quarter margin
SCAN_PER_WORKTREE_SECONDS=180                                     # plan, section "Quiesce and freeze": 180
FIXTURE_STEP_TIMEOUT="${MOVE_FIXTURE_TIMEOUT_SECONDS:-1800}"      # author
MEASURE_TIMEOUT="${MOVE_MEASURE_TIMEOUT_SECONDS:-5400}"           # author; the plan measured 12.5 minutes for the same du
SIZE_TABLE_TIMEOUT="${MOVE_SIZE_TABLE_TIMEOUT_SECONDS:-7200}"     # author
SCAN_TIMEOUT="${MOVE_SCAN_TIMEOUT_SECONDS:-3000}"                 # plan, section "Quiesce and freeze": timeout 3000
KILL_GRACE=30                                                     # plan: timeout --kill-after=30
ROOT_SCOPE="--scope --collect --property=CPUQuota=200% --property=MemoryMax=2G --property=TasksMax=32 --property=IOWeight=10"
USER_SCOPE="--user --scope --property=CPUQuota=100% --property=MemoryMax=1G --property=TasksMax=64 --property=IOWeight=10"

# A path with a space or a quote would break the commands this wizard shows and runs, so refuse it up front.
require_plain_path() {
  [[ "$2" =~ ^/[A-Za-z0-9_./@+-]+$ ]] || { printf 'The setting %s=%s holds a character this wizard does not quote; use a plain path.\n' "$1" "$2" >&2; REPORTED=1; exit 64; }
}
for _name in REPO EXTERNAL_WORKTREES DRIVE DEST_ROOT SNAPSHOTS MOVE_STATE DANGLING FIXTURE_PARENT CLI_GIT_STATE; do
  require_plain_path "$_name" "${!_name}"
done

SELF="$(readlink -f "${BASH_SOURCE[0]}")"
NODE="$(readlink -f "$(command -v node || true)" 2>/dev/null || true)"
PHASE=""
OUTPUT_FILE=""

# ── Step engine: shows a command, runs it only after the owner confirms, checks it, and stops at the first failure ──
STEP_SAYS=""; STEP_CMD=""; STEP_ROLLBACK=""; STEP_CHECK=""; STEP_CHECK_TEXT=""; STEP_OK_CODES="0"
STEP_TIMER=""; STEP_TIMER_MODE="set"; STEP_WINDOW="no"; STEP_WINDOW_START="no"; STEP_ASK=""; STEP_TIMEOUT=""; STEP_NO_MARK="no"
declare -A REDO=()

reset_step() {
  STEP_SAYS=""; STEP_CMD=""; STEP_ROLLBACK=""; STEP_CHECK=""; STEP_CHECK_TEXT=""; STEP_OK_CODES="0"
  STEP_TIMER=""; STEP_TIMER_MODE="set"; STEP_WINDOW="no"; STEP_WINDOW_START="no"; STEP_ASK=""; STEP_TIMEOUT=""; STEP_NO_MARK="no"
}

now_iso() { date --iso-8601=seconds; }
done_dir() { printf '%s/done/%s' "$WIZ" "$PHASE"; }
log_line() { [[ "$DRY_RUN" == "1" ]] && return 0; mkdir --parents "$WIZ/logs"; printf '%s %s\n' "$(now_iso)" "$*" >> "$WIZ/logs/wizard.log"; }

window_running() { [[ -s "$WIZ/window-start" && ! -e "$WIZ/window-end" && -s "$WIZ/window-max-seconds" ]]; }
window_remaining() {
  local start max
  start="$(<"$WIZ/window-start")"; max="$(<"$WIZ/window-max-seconds")"
  printf '%s' $(( max - ($(date +%s) - start) ))
}
window_exceeded() {
  local start max
  start="$(<"$WIZ/window-start")"; max="$(<"$WIZ/window-max-seconds")"
  printf '\n  %s%sThe cut-over window ran past its stated maximum (%s s, started %s).%s\n' "$BOLD" "$RED" "$max" "$(date --date="@$start" --iso-8601=seconds)" "$RESET"
  say "Nothing further runs. The window never extends itself."
  if [[ -e "$(done_dir)/c19-swap" ]]; then
    say "The old path is already the link. Run  $SELF rollback  (fast path: puts the old tree back and thaws it)."
  else
    say "The old tree is still the repository. Run  $SELF thaw  (unfreezes everything and restarts the stopped units)."
  fi
  log_line "window exceeded"
  REPORTED=1
  exit 3
}
window_guard() { if window_running && (( $(window_remaining) <= 0 )); then window_exceeded; fi; }

list_progress() {
  local dir; dir="$(done_dir)"
  if compgen -G "$dir/*" >/dev/null; then
    say "Completed so far (phase $PHASE):"
    local f; for f in "$dir"/*; do note "  - $(basename "$f")  at $(<"$f")"; done
  else
    say "Nothing in phase $PHASE has completed yet."
  fi
}

stop_with() { # stop_with exit_code headline
  REPORTED=1
  printf '\n  %s%s%s%s\n\n' "$BOLD" "$RED" "$2" "$RESET"
  list_progress
  [[ -n "$STEP_ROLLBACK" ]] && say "Rollback for the failed step: $STEP_ROLLBACK"
  say "Log of every step: $WIZ/logs/wizard.log"
  say "To resume: run  $SELF $PHASE  again. Completed steps are skipped and the failed one is offered again."
  [[ "$PHASE" == "cutover" ]] && say "To thaw a frozen repository at any time: $SELF thaw"
  log_line "STOP $2"
  exit "$1"
}

KEEPALIVE_PID=""
REPORTED=0
# On any exit with a failure status that stop_with did not already explain, say what ran last and how to resume.
on_exit() {
  local status=$?
  [[ -n "$KEEPALIVE_PID" ]] && kill "$KEEPALIVE_PID" 2>/dev/null
  if (( status != 0 && REPORTED == 0 )); then
    REPORTED=1
    printf '\n  %s%sUnexpected failure (status %s) after: %s%s\n' "$BOLD" "$RED" "$status" "$BASH_COMMAND" "$RESET"
    [[ -n "$PHASE" ]] && list_progress
    say "To resume: run  $SELF $PHASE  again. To thaw a frozen repository: $SELF thaw"
  fi
  return 0
}
trap on_exit EXIT

# A background loop that renews the sudo login so no step stalls on a password prompt inside a timeout wrapper.
# It ends when this script ends or after a day, whichever comes first.
start_sudo_keepalive() {
  [[ "$DRY_RUN" == "1" || -n "$KEEPALIVE_PID" ]] && return 0
  ( deadline=$(( $(date +%s) + 86400 )); while kill -0 "$$" 2>/dev/null && (( $(date +%s) < deadline )); do sleep 60; sudo --non-interactive --validate 2>/dev/null || exit 0; done ) &
  KEEPALIVE_PID=$!
}

add_seconds() { # add_seconds file seconds mode
  local file="$WIZ/$1" prior=0
  if [[ "$3" == "add" && -s "$file" ]]; then prior="$(<"$file")"; fi
  printf '%s\n' $(( prior + $2 )) > "$file"
}

# run_step ID TITLE  (the STEP_* variables describe the step; they are cleared afterwards)
run_step() {
  local id="$1" title="$2" dir status=0 started output command_to_run remaining deadline shown line
  dir="$(done_dir)"; [[ "$DRY_RUN" == "1" ]] || mkdir --parents "$dir"
  if [[ -e "$dir/$id" && -z "${REDO[$id]:-}" && "$STEP_NO_MARK" == "no" ]]; then
    _STAGE_INDEX=$((_STAGE_INDEX + 1))
    note "stage $_STAGE_INDEX/$TOTAL_STAGES $title: already done at $(<"$dir/$id"); skipped"
    reset_step; return 0
  fi
  stage "$title"
  [[ "$STEP_WINDOW" == "yes" ]] && window_guard
  [[ -n "$STEP_SAYS" ]] && while IFS= read -r line; do say "$line"; done <<< "$STEP_SAYS"
  remaining=0; deadline="$TRANSFER_DEADLINE"
  if [[ "$STEP_WINDOW" == "yes" ]] && window_running; then
    remaining="$(window_remaining)"
    deadline=$(( remaining < TRANSFER_DEADLINE ? remaining : TRANSFER_DEADLINE ))
  fi
  shown="${STEP_CMD//@DEADLINE@/$deadline}"
  printf '\n  %sCommand%s (runs as written by bash -e -o pipefail):\n' "$BOLD" "$RESET"
  while IFS= read -r line; do printf '    %s%s%s\n' "$GREEN" "$line" "$RESET"; done <<< "$shown"
  [[ "$STEP_WINDOW" == "yes" ]] && window_running && note "bounded by timeout: $remaining s, the window's remainder (recomputed when you confirm)"
  [[ -n "$STEP_TIMEOUT" ]] && note "bounded by timeout: $STEP_TIMEOUT s"
  [[ -n "$STEP_CHECK_TEXT" ]] && note "check afterwards: $STEP_CHECK_TEXT"
  [[ -n "$STEP_ROLLBACK" ]] && note "rollback: $STEP_ROLLBACK"
  if [[ "$DRY_RUN" == "1" ]]; then
    warn "dry run: this step is shown, not executed, and not recorded"
    reset_step; return 0
  fi
  if [[ -n "$STEP_ASK" ]]; then
    confirm "$STEP_ASK" || { STEP_ROLLBACK=""; stop_with 2 "Stopped at your answer; nothing was run for step $id."; }
  fi
  confirm "Run this step now?" || { STEP_ROLLBACK=""; stop_with 2 "Stopped at your answer; nothing was run for step $id."; }
  if [[ "$STEP_WINDOW_START" == "yes" && ! -s "$WIZ/window-start" ]]; then date +%s > "$WIZ/window-start"; log_line "window start"; fi
  if [[ "$STEP_WINDOW" == "yes" ]] && window_running; then
    remaining="$(window_remaining)"
    (( remaining > 0 )) || window_exceeded
    deadline=$(( remaining < TRANSFER_DEADLINE ? remaining : TRANSFER_DEADLINE ))
  fi
  command_to_run="${STEP_CMD//@DEADLINE@/$deadline}"
  output="$WIZ/logs/$PHASE-$id.out"; mkdir --parents "$WIZ/logs"
  OUTPUT_FILE="$output"; export OUTPUT_FILE
  log_line "run $PHASE/$id: $command_to_run"
  started=$SECONDS
  set +e
  if [[ "$STEP_WINDOW" == "yes" ]] && window_running; then
    remaining="$(window_remaining)"
    (( remaining > 0 )) || window_exceeded
    timeout --kill-after="$KILL_GRACE" "$remaining" bash -e -o pipefail -c "$command_to_run" < /dev/null 2>&1 | tee "$output"
  elif [[ -n "$STEP_TIMEOUT" ]]; then
    timeout --kill-after="$KILL_GRACE" "$STEP_TIMEOUT" bash -e -o pipefail -c "$command_to_run" < /dev/null 2>&1 | tee "$output"
  else
    bash -e -o pipefail -c "$command_to_run" < /dev/null 2>&1 | tee "$output"
  fi
  status="${PIPESTATUS[0]}"
  set -e
  log_line "exit $status for $PHASE/$id after $((SECONDS - started)) s"
  if [[ " $STEP_OK_CODES " != *" $status "* ]]; then
    stop_with 1 "Step $id ($title) exited $status; its output is above and in $output."
  fi
  if [[ -n "$STEP_CHECK" ]]; then
    set +e
    bash -e -o pipefail -c "$STEP_CHECK" < /dev/null > "$output.check" 2>&1
    status=$?
    set -e
    if (( status != 0 )); then
      cat "$output.check"
      stop_with 1 "Step $id ($title) ran, but its check failed: $STEP_CHECK_TEXT"
    fi
    [[ -s "$output.check" ]] && sed 's/^/    check: /' "$output.check"
    printf '  %s✓ check passed:%s %s\n' "$GREEN" "$RESET" "$STEP_CHECK_TEXT"
  fi
  [[ -n "$STEP_TIMER" ]] && add_seconds "$STEP_TIMER" $((SECONDS - started)) "$STEP_TIMER_MODE"
  [[ "$STEP_NO_MARK" == "no" ]] && now_iso > "$dir/$id"
  reset_step
  pause "Press Enter for the next stage"
}

need_file() { [[ -e "$1" ]] || { printf '%s%sMissing: %s (%s)%s\n' "$BOLD" "$RED" "$1" "$2" "$RESET" >&2; REPORTED=1; exit 66; }; }
phase_done() { [[ -e "$WIZ/done/$1/$2" ]]; }

# ── Start-up checks that change nothing ──
startup_checks() {
  [[ "$(id -u)" != "0" ]] || { echo "Run this as your own user, not as root: each root step asks sudo itself."; REPORTED=1; exit 64; }
  local here; here="$(readlink -f "$PWD")"
  case "$SELF" in "$REPO"/*|"$(readlink -f "$REPO")"/*)
    echo "This script sits inside the repository, so bash holds it open there and the holder scans would report it."
    echo "Copy it out first:  cp $SELF ${HOME_DIR}/repository-move-wizard.sh  and run that copy."; REPORTED=1; exit 64 ;;
  esac
  case "$here" in "$REPO"|"$REPO"/*|"$(readlink -f "$REPO")"|"$(readlink -f "$REPO")"/*)
    echo "The current folder is inside the repository; the holder scans would report this shell. cd out of it first."; REPORTED=1; exit 64 ;;
  esac
  [[ -n "$NODE" && -x "$NODE" ]] || { echo "node is not on PATH; sudo needs its absolute path."; REPORTED=1; exit 66; }
  local tool
  for tool in btrfs rsync unshare runuser systemd-run sudo findmnt mountpoint timeout awk sed; do
    command -v "$tool" >/dev/null || { echo "Missing tool: $tool"; REPORTED=1; exit 66; }
  done
  need_file "$MOVE_SCRIPT" "the copy script from the plan, section The copy"
  need_file "$SCAN_SCRIPT" "the baseline script from the plan, section Quiesce and freeze"
  mkdir --parents --mode=0700 "$MOVE_STATE" "$WIZ" "$WIZ/logs"
}

# ── Internal helpers the steps call (read-only computations, written here so the owner can read them) ──
footprint_of() { awk 'END { print $2 + $3 }' "$1"; } # btrfs filesystem du --summarize --raw: Total Exclusive "Set shared" path

internal_preflight() {
  local main_fp external_bytes total need dest_free nvme_free gib=$((1024 * 1024 * 1024)) margin
  main_fp="$(footprint_of "$WIZ/main-du.txt")"
  external_bytes="$(awk '{ sum += $1 } END { print sum + 0 }' "$WIZ/external-du.txt")"
  total=$(( main_fp + external_bytes ))
  margin=$(( total * MARGIN_PERCENT / 100 ))
  need=$(( total + margin ))
  dest_free="$(awk -v a="$(stat --file-system --format=%a "$DRIVE")" -v s="$(stat --file-system --format=%S "$DRIVE")" 'BEGIN { printf "%.0f", a * s }')"
  nvme_free="$(awk -v a="$(stat --file-system --format=%a "$HOME_DIR")" -v s="$(stat --file-system --format=%S "$HOME_DIR")" 'BEGIN { printf "%.0f", a * s }')"
  printf 'nested checkout footprint (exclusive + set shared): %s GiB\n' $(( main_fp / gib ))
  printf 'external worktrees (du, no sharing): %s GiB\n' $(( external_bytes / gib ))
  printf 'estimate: %s GiB; with the plan margin of %s percent: %s GiB\n' $(( total / gib )) "$MARGIN_PERCENT" $(( need / gib ))
  printf '860 free now: %s GiB; free after the estimate and margin: %s GiB; required: at least %s GiB\n' $(( dest_free / gib )) $(( (dest_free - need) / gib )) "$MIN_FREE_GIB"
  printf 'NVMe free now: %s GiB; required: at least %s GiB while source snapshots exist\n' $(( nvme_free / gib )) "$NVME_MIN_FREE_GIB"
  if (( dest_free - need < MIN_FREE_GIB * gib )); then echo "REFUSED: the 860 would be left under ${MIN_FREE_GIB} GiB free."; return 1; fi
  if (( nvme_free < NVME_MIN_FREE_GIB * gib )); then echo "REFUSED: the NVMe is under ${NVME_MIN_FREE_GIB} GiB free."; return 1; fi
  echo "pre-flight passed"
}

internal_window_maximum() {
  local first scan du_seconds derived chosen="${MOVE_WINDOW_MAX_SECONDS:-}"
  first="$(<"$WIZ/first-pass-seconds")"; scan="$(<"$WIZ/scan-seconds")"; du_seconds="$(<"$WIZ/du-seconds")"
  derived=$(( first + first + 2 * scan + 2 * du_seconds ))
  printf 'first pass, measured: %s s (the final pass sends only what changed, so a full first pass is its upper bound)\n' "$first"
  printf 'one scan of every worktree, measured: %s s (taken twice in the window: frozen baseline and staged table)\n' "$scan"
  printf 'one footprint measurement of the checkout, measured: %s s (taken twice: source and copy)\n' "$du_seconds"
  printf 'content-check allowance, the author'"'"'s choice: one more first-pass duration, %s s, because fsck, the checksum comparisons and the counts read the copy about once\n' "$first"
  printf 'derived maximum = first pass + content-check allowance + 2 x scan + 2 x footprint = %s s\n' "$derived"
  if [[ -n "$chosen" ]]; then
    (( chosen <= derived )) || { echo "REFUSED: MOVE_WINDOW_MAX_SECONDS=$chosen is above the derived maximum $derived; the window may be shortened, never lengthened."; return 1; }
    derived="$chosen"; printf 'shortened by the owner to %s s\n' "$derived"
  fi
  printf '%s\n' "$derived" > "$WIZ/window-max-seconds"
  printf 'stated maximum of the window: %s s (%s minutes)\n' "$derived" $(( derived / 60 ))
}

# Every subvolume the verification must check by content: the checkout, every worktree with a non-clean baseline row, and
# the six largest and six smallest by the size table taken before the window.
internal_select_verify() {
  local name path record
  : > "$WIZ/final-map.tsv"
  for record in "${STATE_DIR_FOR_SELECT:-$MOVE_STATE}"/f*.snapshot.json; do
    name="$(basename "$record" .snapshot.json)"
    path="$(sed -n 's/.*"path":"\([^"]*\)".*/\1/p' "$record")"
    printf '%s\t%s\n' "$name" "$path" >> "$WIZ/final-map.tsv"
  done
  {
    awk -F'\t' 'NR == 1 { print $2 }' "$WIZ/final-map.tsv"
    awk -F'\t' 'NR > 1 && ($3 + 0 > 0 || $4 + 0 > 0 || $5 != "" || $6 == "true") { print $1 }' "$WIZ/baseline-frozen.tsv"
    sort --numeric-sort --key=1,1 "$WIZ/subvolume-sizes.txt" | tail --lines=6 | cut --fields=2
    sort --numeric-sort --key=1,1 "$WIZ/subvolume-sizes.txt" | head --lines=6 | cut --fields=2
  } | sort --unique > "$WIZ/verify-paths.txt"
  awk -F'\t' 'NR == FNR { want[$1] = 1; next } ($2 in want) { print $1 "\t" $2 }' "$WIZ/verify-paths.txt" "$WIZ/final-map.tsv" > "$WIZ/verify-set.tsv"
  printf 'content checks cover %s of %s subvolumes\n' "$(wc --lines < "$WIZ/verify-set.tsv")" "$(wc --lines < "$WIZ/final-map.tsv")"
}

holder_patterns_file() { # prints one -lname pattern per line for every place a writer could hold open
  {
    printf '%s*\n' "$REPO" "$EXTERNAL_WORKTREES"
    if [[ -s "$WIZ/porcelain-start.txt" ]]; then
      sed -n 's/^worktree //p' "$WIZ/porcelain-start.txt" | awk -v repo="$REPO" -v ext="$EXTERNAL_WORKTREES" -v home="$HOME_DIR" -v drive="$DRIVE" '
        index($0, repo) == 1 || index($0, ext) == 1 { next }
        { print $0 "*"; if (index($0, home "/temp/") == 1) print drive "/temp/" substr($0, length(home "/temp/") + 1) "*" }'
    fi
  } | sort --unique
}

# ── Subcommands ──
ext_names() { /usr/bin/find "$EXTERNAL_WORKTREES" -mindepth 1 -maxdepth 1 -type d -printf '%f\n' | sort; }

holder_scan_command() { # holder_scan_command output-name
  local patterns="" pattern
  while IFS= read -r pattern; do patterns+="${patterns:+ -o }-lname '$pattern'"; done < <(holder_patterns_file)
  printf '%s' "sudo /usr/bin/find /proc -maxdepth 3 \\( -name cwd -o -path '/proc/*/fd/*' \\) \\( $patterns \\) -printf '%p %l\\n' > $WIZ/$1.txt 2> $WIZ/$1.err"
}

sudo_login() {
  STEP_NO_MARK="yes"
  STEP_SAYS="The root steps use sudo. This asks for your password once; a background loop then renews it (it ends with this script) so no step stalls on a prompt."
  STEP_CMD="sudo --validate"
  STEP_CHECK="sudo --non-interactive true"; STEP_CHECK_TEXT="sudo works without a prompt"
  STEP_ROLLBACK="nothing changed; sudo --reset-timestamp forgets the login"
  run_step "sudo-$PHASE" "Root access"
  start_sudo_keepalive
}

prepare_main() {
  PHASE=prepare; TOTAL_STAGES=25; _STAGE_INDEX=0
  _clear
  printf '\n%s%s  Move the repository to the 860 drive: prepare (nothing is cut over)%s\n' "$BOLD" "$BLUE" "$RESET"
  say "Steps: sudo login, fixture test on loop images, inventory R0, space check, first pass (print then run)."
  say "The repository stays writable. Every root command is shown first and runs only after you answer y."
  say "Nothing is deleted by this script. A failed step stops it and prints how to resume."
  [[ "$DRY_RUN" == "1" ]] && warn "DRY RUN: steps are displayed, never executed or recorded"
  pause "Press Enter to start"

  sudo_login

  # ── Fixture test (plan, section "Fixture test before the real run"): F1 to F8 on throwaway loop images ──
  STEP_SAYS="Fixture F1a: a fresh private folder under $FIXTURE_PARENT. Only what this run creates is ever touched."
  STEP_CMD="mkdir --parents $FIXTURE_PARENT && mktemp --directory $FIXTURE_PARENT/send-fixture.XXXXXX | tee $WIZ/fixture-path"
  STEP_CHECK="test -d \"\$(cat $WIZ/fixture-path)\""; STEP_CHECK_TEXT="the fixture folder exists"
  STEP_ROLLBACK="the folder is empty; its removal is printed in the last fixture stage"
  run_step f1a-folder "Fixture: folder"
  local FX="$FIXTURE_PARENT/send-fixture.DRYRUN"
  [[ -s "$WIZ/fixture-path" ]] && FX="$(<"$WIZ/fixture-path")"
  require_plain_path FIXTURE "$FX"

  STEP_SAYS="Fixture F1: two 3G sparse images, a btrfs on each, mounted by loop. No real disk is touched."
  STEP_CMD="set -o noclobber
: > $FX/source.img
: > $FX/dest.img
truncate --no-create --size=3G $FX/source.img $FX/dest.img
sudo mkfs.btrfs --quiet $FX/source.img
sudo mkfs.btrfs --quiet $FX/dest.img
sudo mkdir $FX/source $FX/dest
sudo mount -o loop $FX/source.img $FX/source
sudo mount -o loop $FX/dest.img $FX/dest
sudo mkdir $FX/dest/recv
mkdir $FX/snap $FX/state
findmnt --noheadings --output SOURCE,TARGET $FX/source $FX/dest"
  STEP_CHECK="test \"\$(findmnt --noheadings --output SOURCE,TARGET $FX/source $FX/dest | grep --count '^/dev/loop')\" = 2"
  STEP_CHECK_TEXT="both mount lines are loop devices (a missing line stops the test)"
  STEP_ROLLBACK="sudo umount $FX/source $FX/dest (whichever is mounted); the images are deleted by you from the list printed in the last fixture stage"
  STEP_TIMEOUT="$FIXTURE_STEP_TIMEOUT"
  run_step f1-images "Fixture F1: loop images"

  STEP_SAYS="Fixture F2: a main checkout that is a subvolume with a Git repository and two worktree subvolumes sharing one 300 MiB extent by reflink."
  STEP_CMD="sudo btrfs subvolume create $FX/source/main
sudo chown $USER_NAME:$GROUP_NAME $FX/source/main
/usr/bin/git -C $FX/source/main init --quiet
head --bytes=300M /dev/urandom > $FX/source/main/big
/usr/bin/git -C $FX/source/main add big
/usr/bin/git -C $FX/source/main -c user.name=t -c user.email=t@t commit --quiet --message base
mkdir --parents $FX/source/main/.claude/worktrees
sudo btrfs subvolume create $FX/source/main/.claude/worktrees/a
sudo btrfs subvolume create $FX/source/main/.claude/worktrees/b
sudo chown $USER_NAME:$GROUP_NAME $FX/source/main/.claude/worktrees/a $FX/source/main/.claude/worktrees/b
/usr/bin/git -C $FX/source/main worktree add --force --quiet $FX/source/main/.claude/worktrees/a -b a
/usr/bin/git -C $FX/source/main worktree add --force --quiet $FX/source/main/.claude/worktrees/b -b b
cp --reflink=always $FX/source/main/big $FX/source/main/.claude/worktrees/a/big.copy
cp --reflink=always $FX/source/main/big $FX/source/main/.claude/worktrees/b/big.copy
sudo btrfs filesystem du --summarize $FX/source/main | tee $FX/source-baseline.txt
sudo btrfs subvolume list $FX/source > $FX/inventory.txt"
  STEP_CHECK="test \"\$(grep --count -E ' path main(/.claude/worktrees/[ab])?\$' $FX/inventory.txt)\" = 3"
  STEP_CHECK_TEXT="the filesystem list shows main and its two worktree subvolumes"
  STEP_ROLLBACK="nothing outside the fixture changed"
  STEP_TIMEOUT="$FIXTURE_STEP_TIMEOUT"
  run_step f2-populate "Fixture F2: source tree"

  local fixture_args="--main=$FX/source/main --snapshots=$FX/snap --received=$FX/dest/recv --final=$FX/dest/final --state=$FX/state --inventory=$FX/inventory.txt --inventory-main=main --inventory-prefix=main/=$FX/source/main/ --deadline-seconds=600 --min-free-gib=1"
  STEP_SAYS="Fixture F3a: the real copy script in print mode against the fixture. It runs nothing; it proves the inventory path mapping."
  STEP_CMD="$NODE $MOVE_SCRIPT --pass=first $fixture_args > $FX/print-first.txt"
  STEP_CHECK="test \"\$(grep --count '^btrfs subvolume snapshot -r' $FX/print-first.txt)\" = 3 && grep --fixed-strings 'inventory agrees: 2 nested subvolumes' \"\$OUTPUT_FILE\""
  STEP_CHECK_TEXT="three snapshots printed and the inventory agrees with Git (main, a, b)"
  STEP_ROLLBACK="nothing ran"
  run_step f3a-print "Fixture F3a: print mode"

  STEP_SAYS="Fixture F3b: the first pass for real, as root, on the loop images."
  STEP_CMD="sudo $NODE $MOVE_SCRIPT --run --pass=first $fixture_args"
  STEP_CHECK="grep --fixed-strings 'pass first finished' \"\$OUTPUT_FILE\" && ls $FX/state/s000.received.json $FX/state/s001.received.json $FX/state/s002.received.json"
  STEP_CHECK_TEXT="'pass first finished' and a received record for s000, s001, s002"
  STEP_ROLLBACK="the images are throwaway; nothing real changed"
  STEP_TIMEOUT="$FIXTURE_STEP_TIMEOUT"
  run_step f3b-first "Fixture F3b: first pass"

  STEP_SAYS="Fixture F3c: change content after the first pass (a new file in worktree b, an empty commit in main)."
  STEP_CMD="echo changed >> $FX/source/main/.claude/worktrees/b/extra.txt
/usr/bin/git -C $FX/source/main -c user.name=t -c user.email=t@t commit --allow-empty --quiet --message after"
  STEP_CHECK="test -s $FX/source/main/.claude/worktrees/b/extra.txt"; STEP_CHECK_TEXT="the change exists"
  STEP_ROLLBACK="throwaway fixture"
  run_step f3c-change "Fixture F3c: change"

  STEP_SAYS="Fixture F3d: the final pass with the freeze, as the cut-over will run it."
  STEP_CMD="sudo $NODE $MOVE_SCRIPT --run --freeze --pass=final $fixture_args"
  STEP_CHECK="grep --fixed-strings 'pass final finished' \"\$OUTPUT_FILE\" && ls $FX/state/f000.received.json $FX/state/f001.received.json $FX/state/f002.received.json $FX/state/f000.placed.json $FX/state/f001.placed.json $FX/state/f002.placed.json"
  STEP_CHECK_TEXT="'pass final finished' and a received and a placed record for f000, f001, f002"
  STEP_ROLLBACK="throwaway fixture; sudo btrfs property set -ts <fixture path> ro false thaws a fixture subvolume"
  STEP_TIMEOUT="$FIXTURE_STEP_TIMEOUT"
  run_step f3d-final "Fixture F3d: final pass"

  STEP_SAYS="Fixture F4: compare every subvolume, check the received state, and check that reflink sharing survived (a copy that lost sharing is larger than the source)."
  STEP_CMD="for path in main main/.claude/worktrees/a main/.claude/worktrees/b; do
  sudo rsync --archive --checksum --dry-run --itemize-changes --delete --one-file-system --omit-dir-times $FX/source/\$path/ $FX/dest/final/\${path#main}/
done > $FX/rsync-compare.txt
sudo btrfs property get -ts $FX/dest/recv/f001 ro
sudo btrfs subvolume show $FX/dest/recv/f001 | awk '\$1 == \"Received\" && \$2 == \"UUID:\" { print \"received \" \$3 }'
sudo btrfs subvolume show $FX/snap/f001 | awk '\$1 == \"UUID:\" { print \"sent \" \$2 }'
sudo btrfs filesystem du --summarize --raw $FX/dest/final | tee $FX/dest-du.txt
sudo btrfs filesystem du --summarize --raw $FX/source/main | tee $FX/source-du.txt
df --block-size=1M $FX/source $FX/dest"
  STEP_CHECK="test ! -s $FX/rsync-compare.txt && grep --fixed-strings 'ro=true' \"\$OUTPUT_FILE\" && test \"\$(grep '^received ' \"\$OUTPUT_FILE\" | cut --delimiter=' ' --fields=2)\" = \"\$(grep '^sent ' \"\$OUTPUT_FILE\" | cut --delimiter=' ' --fields=2)\" && test \$(( \$(awk 'END { print \$2 + \$3 }' $FX/dest-du.txt) * 100 )) -le \$(( \$(awk 'END { print \$2 + \$3 }' $FX/source-du.txt) * $SHARING_LIMIT_PERCENT ))"
  STEP_CHECK_TEXT="rsync prints nothing for all three, ro=true, received UUID equals sent UUID, copy footprint within ${SHARING_LIMIT_PERCENT} percent of the source (sharing kept)"
  STEP_ROLLBACK="read-only checks; nothing to undo. If sharing was lost the method is wrong for this repository: stop and report"
  STEP_TIMEOUT="$FIXTURE_STEP_TIMEOUT"
  run_step f4-compare "Fixture F4: compare"

  STEP_SAYS="Fixture F5a: a first pass with a one-second deadline on fresh folders. The plan expects it to stop; a copy that finishes inside a second is also accepted, because F5b makes the interrupted case deterministically."
  STEP_CMD="sudo mkdir $FX/dest/recv-f5a
mkdir $FX/snap-f5a $FX/state-f5a
sudo $NODE $MOVE_SCRIPT --run --pass=first --main=$FX/source/main --snapshots=$FX/snap-f5a --received=$FX/dest/recv-f5a --final=$FX/dest/final-f5a --state=$FX/state-f5a --inventory=$FX/inventory.txt --inventory-main=main --inventory-prefix=main/=$FX/source/main/ --deadline-seconds=1 --min-free-gib=1; echo \"script exit status: \$?\""
  STEP_CHECK="grep --extended-regexp 'script exit status: [01]' \"\$OUTPUT_FILE\""; STEP_CHECK_TEXT="the run ended with status 0 (finished) or 1 (stopped at the deadline)"
  STEP_ROLLBACK="a partial copy in $FX/dest/recv-f5a, if any, goes with the images"
  STEP_TIMEOUT="$FIXTURE_STEP_TIMEOUT"
  run_step f5a-deadline "Fixture F5a: deadline"

  STEP_SAYS="Fixture F5b: a leftover partial receive (a subvolume named s000 with no completion record). The script must refuse and name the exact delete for you to run."
  STEP_CMD="sudo mkdir $FX/dest/recv-f5b
sudo btrfs subvolume create $FX/dest/recv-f5b/s000
mkdir $FX/snap-f5b $FX/state-f5b
sudo $NODE $MOVE_SCRIPT --run --pass=first --main=$FX/source/main --snapshots=$FX/snap-f5b --received=$FX/dest/recv-f5b --final=$FX/dest/final-f5b --state=$FX/state-f5b --inventory=$FX/inventory.txt --inventory-main=main --inventory-prefix=main/=$FX/source/main/ --deadline-seconds=600 --min-free-gib=1"
  STEP_OK_CODES="1"
  STEP_CHECK="grep --fixed-strings 'exists without a completion record' \"\$OUTPUT_FILE\" && grep --fixed-strings 'btrfs subvolume delete' \"\$OUTPUT_FILE\""
  STEP_CHECK_TEXT="exit status 1 with 'exists without a completion record' and the printed 'btrfs subvolume delete'"
  STEP_ROLLBACK="the leftover is inside the throwaway image"
  STEP_TIMEOUT="$FIXTURE_STEP_TIMEOUT"
  run_step f5b-leftover "Fixture F5b: partial receive"

  STEP_SAYS="Fixture F5c: a stream with one flipped byte must be refused by btrfs receive (a checksum error)."
  STEP_CMD="sudo bash -c 'btrfs send $FX/snap/s000 > $FX/stream.bin' && sudo chown $USER_NAME:$GROUP_NAME $FX/stream.bin
cp $FX/stream.bin $FX/stream.orig
python3 -I -c \"import sys; p=sys.argv[1]; f=open(p,'r+b'); f.seek(100000); b=f.read(1); f.seek(100000); f.write(bytes([b[0]^255]))\" $FX/stream.bin
if cmp --silent $FX/stream.orig $FX/stream.bin; then echo 'the flip changed nothing'; exit 1; fi
sudo mkdir $FX/dest/recv-f5c
if sudo btrfs receive $FX/dest/recv-f5c < $FX/stream.bin; then echo 'UNEXPECTED: the corrupted stream was accepted'; exit 1; else echo 'receive refused the corrupted stream, as required'; fi"
  STEP_CHECK="grep --fixed-strings 'receive refused the corrupted stream' \"\$OUTPUT_FILE\""
  STEP_CHECK_TEXT="btrfs receive refused the flipped stream"
  STEP_ROLLBACK="a partial subvolume under $FX/dest/recv-f5c, if any, goes with the images"
  STEP_TIMEOUT="$FIXTURE_STEP_TIMEOUT"
  run_step f5c-corrupt "Fixture F5c: corrupted stream"

  STEP_SAYS="Fixture F6: the staged-verification pattern. A private mount namespace binds the copy over the source path; Git then reads the copy. Git runs as you, never as root."
  STEP_CMD="sudo unshare --mount --propagation private bash -euo pipefail -c \"
  mount --bind $FX/dest/final $FX/source/main
  runuser -u $USER_NAME -- env HOME=$HOME_DIR /usr/bin/git --no-optional-locks -C $FX/source/main worktree list
  runuser -u $USER_NAME -- env HOME=$HOME_DIR /usr/bin/git --no-optional-locks -C $FX/source/main fsck --full
  runuser -u $USER_NAME -- env HOME=$HOME_DIR $NODE $SCAN_SCRIPT $FX/source/main $FX/staged.tsv 60
\""
  STEP_CHECK="test \"\$(wc --lines < $FX/staged.tsv)\" = 4 && grep --fixed-strings $FX/source/main/.claude/worktrees/a \"\$OUTPUT_FILE\""
  STEP_CHECK_TEXT="worktree list shows the source paths and staged.tsv is the table of the three staged worktrees"
  STEP_ROLLBACK="the bind exists only inside the private namespace and vanishes when the command ends"
  STEP_TIMEOUT="$FIXTURE_STEP_TIMEOUT"
  run_step f6-staged "Fixture F6: staged verification"

  STEP_SAYS="Fixture F7: can a mount cover an immutable directory? Unmounts the two fixture mounts, then mounts the destination image on a +i folder."
  STEP_CMD="sudo umount $FX/source $FX/dest
sudo mkdir $FX/mp
sudo chattr +i $FX/mp
sudo mount -o loop $FX/dest.img $FX/mp
echo \"while mounted: \$(lsattr -d $FX/mp)\"
sudo umount $FX/mp
echo \"after unmount: \$(lsattr -d $FX/mp)\"
sudo chattr -i $FX/mp"
  STEP_CHECK="grep --extended-regexp '^after unmount: .{4}i' \"\$OUTPUT_FILE\" && ! grep --extended-regexp '^while mounted: .{4}i' \"\$OUTPUT_FILE\""
  STEP_CHECK_TEXT="the mount succeeded; while mounted the directory shows no i flag; after unmount it shows i again"
  STEP_ROLLBACK="sudo umount $FX/mp if still mounted; sudo chattr -i $FX/mp"
  STEP_TIMEOUT="$FIXTURE_STEP_TIMEOUT"
  run_step f7-immutable "Fixture F7: mount over immutable"

  STEP_SAYS="Fixture F8: cleanup. This script never deletes. The next command only prints the removals for you to run when you are done with the fixture."
  STEP_CMD="printf '%s\n' \"sudo rmdir $FX/mp $FX/source $FX/dest\" \"rm -- $FX/source.img $FX/dest.img\" \"(then remove $FX and its remaining files yourself when you no longer need the logs)\""
  STEP_CHECK="grep --count 'rmdir' \"\$OUTPUT_FILE\""; STEP_CHECK_TEXT="the removals are printed"
  STEP_ROLLBACK="nothing to undo"
  run_step f8-cleanup-printed "Fixture F8: removals printed"

  # ── Inventory R0 (plan, section "The copy", Inventory) ──
  STEP_SAYS="R0: the filesystem's own list of every subvolume of the NVMe filesystem, and any mount inside the checkout. The copy script keeps the ones below the checkout."
  STEP_CMD="sudo btrfs subvolume list /var/home > $INVENTORY
sudo findmnt --list --output TARGET,SOURCE,FSTYPE | grep --fixed-strings $REPO || echo 'no mount inside the tree'"
  STEP_CHECK="test -s $INVENTORY && grep --extended-regexp --quiet ' path $INVENTORY_MAIN(/|\$)' $INVENTORY && grep --fixed-strings 'no mount inside the tree' \"\$OUTPUT_FILE\""
  STEP_CHECK_TEXT="the list is not empty, names the checkout, and no mount sits inside the tree (a mount needs your written disposition first)"
  STEP_ROLLBACK="read-only; the list file can be regenerated"
  run_step r0-inventory "Inventory R0"

  local first_args="--main=$REPO --snapshots=$SNAPSHOTS --received=$RECEIVED --final=$FINAL --state=$MOVE_STATE --inventory=$INVENTORY --inventory-main=$INVENTORY_MAIN --deadline-seconds=$TRANSFER_DEADLINE --min-free-gib=$MIN_FREE_GIB"
  STEP_SAYS="Reconcile: the copy script compares the filesystem's list with Git's registered worktrees and refuses on a difference in either direction. This is print mode: nothing is copied."
  STEP_CMD="$NODE $MOVE_SCRIPT --pass=first $first_args > $WIZ/reconcile-print.txt"
  STEP_CHECK="grep --extended-regexp 'inventory agrees: [0-9]+ nested subvolumes' \"\$OUTPUT_FILE\""
  STEP_CHECK_TEXT="the script reports 'inventory agrees'"
  STEP_ROLLBACK="read-only. On a refusal the script names each subvolume Git does not know or each registered one that is not a subvolume; give each a written disposition (copy with its own entry, or exclude) before going on"
  run_step r0-reconcile "Inventory reconciles with Git"

  # ── Pre-flight space check (plan, section "Capacity policy") ──
  STEP_SAYS="Pre-flight 1 of 3: the footprint of the nested checkout with extent sharing counted once, as root so unreadable files are included. The plan measured about 12.5 minutes for it."
  STEP_CMD="sudo systemd-run $ROOT_SCOPE timeout --kill-after=$KILL_GRACE $MEASURE_TIMEOUT btrfs filesystem du --summarize --raw $REPO | tee $WIZ/main-du.txt"
  STEP_CHECK="awk 'END { exit !(NF >= 4 && \$2 + \$3 > 0) }' $WIZ/main-du.txt"; STEP_CHECK_TEXT="the output has a total row with exclusive plus set shared above zero"
  STEP_ROLLBACK="read-only"
  STEP_TIMER="du-seconds"
  run_step p3a-footprint "Pre-flight: checkout footprint"

  local names; names="$(ext_names | sed "s|^|$EXTERNAL_WORKTREES/|" | tr '\n' ' ')"
  STEP_SAYS="Pre-flight 2 of 3: the on-disk size of each external worktree (plain directories on the NVMe, nothing shared on the 860)."
  STEP_CMD="sudo systemd-run $ROOT_SCOPE timeout --kill-after=$KILL_GRACE $MEASURE_TIMEOUT bash -c 'for p in \"\$@\"; do du --summarize --one-file-system --block-size=1 -- \"\$p\"; done' _ $names | tee $WIZ/external-du.txt"
  STEP_CHECK="test -s $WIZ/external-du.txt"; STEP_CHECK_TEXT="one size row per external folder"
  STEP_ROLLBACK="read-only"
  run_step p3b-external "Pre-flight: external worktrees"

  STEP_SAYS="Pre-flight 3 of 3: the rule from the plan. The 860's free space after the estimate plus a quarter margin must stay at least ${MIN_FREE_GIB} GiB, and the NVMe at least ${NVME_MIN_FREE_GIB} GiB. A refusal here is the rule working: free space or the estimate changed since the plan was written."
  STEP_CMD="bash $SELF __preflight"
  STEP_CHECK="grep --fixed-strings 'pre-flight passed' \"\$OUTPUT_FILE\""; STEP_CHECK_TEXT="the script prints 'pre-flight passed'"
  STEP_ROLLBACK="read-only. If refused, free space on the 860 or lower the scope (the plan's scope four) before running prepare again"
  run_step p3c-rule "Pre-flight: the rule"

  # ── Folders, print mode, first pass ──
  STEP_SAYS="The folders from the plan: the snapshot folder on the NVMe, and on the 860 the 0700 repository folder, the received folder and the external-worktrees folder. The 860 must be mounted first."
  STEP_CMD="mountpoint --quiet $DRIVE
test \"\$(findmnt --noheadings --output UUID --target $DRIVE)\" != \"\$(findmnt --noheadings --output UUID --target $HOME_DIR)\"
[ -d $SNAPSHOTS ] || mkdir --mode=0700 $SNAPSHOTS
[ -d $DEST_ROOT ] || sudo mkdir --mode=0700 $DEST_ROOT
sudo chown $USER_NAME:$GROUP_NAME $DEST_ROOT
[ -d $RECEIVED ] || mkdir --mode=0700 $RECEIVED
[ -d $EXTERNAL_FINAL ] || mkdir --mode=0700 $EXTERNAL_FINAL
stat --format='%U:%G %a %n' $SNAPSHOTS $DEST_ROOT $RECEIVED $EXTERNAL_FINAL"
  STEP_CHECK="test \"\$(stat --format='%U:%G %a' $SNAPSHOTS $DEST_ROOT $RECEIVED $EXTERNAL_FINAL | sort --unique)\" = '$USER_NAME:$GROUP_NAME 700'"
  STEP_CHECK_TEXT="all four folders are $USER_NAME:$GROUP_NAME mode 700"
  STEP_ROLLBACK="empty folders only: rmdir $RECEIVED $EXTERNAL_FINAL $DEST_ROOT $SNAPSHOTS (yours to run; this script deletes nothing)"
  run_step p4a-folders "Create the folders"

  STEP_SAYS="First pass, print mode: every step the real run will perform, saved to $WIZ/first-pass-print.txt. READ IT. The lines below are the first and last of it."
  STEP_CMD="$NODE $MOVE_SCRIPT --pass=first $first_args > $WIZ/first-pass-print.txt
head --lines=6 $WIZ/first-pass-print.txt
echo ...
tail --lines=2 $WIZ/first-pass-print.txt
echo \"snapshots printed: \$(grep --count '^btrfs subvolume snapshot -r' $WIZ/first-pass-print.txt); sends printed: \$(grep --count 'btrfs send' $WIZ/first-pass-print.txt)\""
  STEP_CHECK="test \"\$(grep --count '^btrfs subvolume snapshot -r' $WIZ/first-pass-print.txt)\" = \"\$(grep --count 'btrfs send' $WIZ/first-pass-print.txt)\" && grep --fixed-strings 'inventory agrees' \"\$OUTPUT_FILE\""
  STEP_CHECK_TEXT="one send per snapshot and the inventory agrees"
  STEP_ROLLBACK="read-only"
  run_step p4b-print "First pass: print mode"

  STEP_SAYS="First pass, for real. The repository stays writable; no window, no freeze. Each transfer has the script's own deadline ($TRANSFER_DEADLINE s) and its own systemd scope (CPUQuota 200%, MemoryMax 2G, TasksMax 32, IOWeight 10). The script has no total limit, only that per-transfer one; Ctrl-C is safe while the registered worktrees stay the same: a rerun resumes from the state records, and it refuses if a worktree was added or removed since the pass started."
  STEP_ASK="Have you read $WIZ/first-pass-print.txt and is it what you expect?"
  STEP_CMD="if [ -s $MOVE_STATE/first-pass-manifest.tsv ]; then
  $NODE $MOVE_SCRIPT --pass=first $first_args | awk '/^btrfs subvolume snapshot -r /{ print \$5 }' | cmp --silent - <(cut --fields=2 $MOVE_STATE/first-pass-manifest.tsv) || { echo 'STOP: worktrees changed since this first pass started, and the copy script keys its records by position; finish from a fresh state folder'; exit 1; }
fi
sudo $NODE $MOVE_SCRIPT --run --pass=first $first_args"
  STEP_CHECK="grep --fixed-strings 'pass first finished' \"\$OUTPUT_FILE\" && test \"\$(ls $MOVE_STATE | grep --count '^s[0-9]*\\.received\\.json\$')\" = \"\$(wc --lines < $MOVE_STATE/first-pass-manifest.tsv)\""
  STEP_CHECK_TEXT="'pass first finished' and one received record per manifest row"
  STEP_ROLLBACK="nothing on the NVMe tree changed (snapshots only). A partial receive is named by the script with the exact 'btrfs subvolume delete' for you to run"
  STEP_TIMER="first-pass-seconds"; STEP_TIMER_MODE="add"
  run_step p4c-first "First pass: run"

  STEP_SAYS="External worktrees (plain directories under $EXTERNAL_WORKTREES): pass one is a new subvolume per folder and a root rsync into it while everything runs. Folders: $(ext_names | tr '\n' ' ')"
  STEP_CMD="for name in $(ext_names | tr '\n' ' '); do
  [ -d $EXTERNAL_FINAL/\$name ] || sudo btrfs subvolume create $EXTERNAL_FINAL/\$name
  sudo systemd-run $ROOT_SCOPE timeout --kill-after=$KILL_GRACE $EXTERNAL_RSYNC_DEADLINE rsync --archive --hard-links --acls --xattrs --numeric-ids --one-file-system $EXTERNAL_WORKTREES/\$name/ $EXTERNAL_FINAL/\$name/
done"
  STEP_CHECK="for name in $(ext_names | tr '\n' ' '); do test -d $EXTERNAL_FINAL/\$name || exit 1; done"
  STEP_CHECK_TEXT="every external folder has a copy"
  STEP_ROLLBACK="the sources are untouched; the copies are new subvolumes under $EXTERNAL_FINAL (delete them yourself with rmdir after emptying, or btrfs subvolume delete as root)"
  run_step p4d-external-first "External worktrees: pass one"

  STEP_SAYS="Size table: the on-disk size of every subvolume, taken now (outside any window) so the cut-over verification can choose the six largest and six smallest."
  STEP_CMD="cut --fields=2 $MOVE_STATE/first-pass-manifest.tsv | sudo systemd-run $ROOT_SCOPE timeout --kill-after=$KILL_GRACE $SIZE_TABLE_TIMEOUT xargs --delimiter='\\n' du --summarize --one-file-system --block-size=1M -- > $WIZ/subvolume-sizes.txt"
  STEP_CHECK="test \"\$(wc --lines < $WIZ/subvolume-sizes.txt)\" = \"\$(wc --lines < $MOVE_STATE/first-pass-manifest.tsv)\""
  STEP_CHECK_TEXT="one size row per manifest row"
  STEP_ROLLBACK="read-only"
  run_step p4e-sizes "Size table"

  # ── Clear stop ──
  _clear
  printf '\n%s%s  Prepare is finished. Nothing was cut over.%s\n\n' "$BOLD" "$GREEN" "$RESET"
  say "The repository is still at $REPO, writable, and the first copy is on the 860."
  say "STOP here. Start the cut-over only when the coordinator says no agent is working in any worktree:"
  say "    $SELF cutover"
  say "The cut-over window refuses commits, and it has a stated maximum duration that it will not exceed."
  log_line "prepare finished"
}

cutover_main() {
  PHASE=cutover; TOTAL_STAGES=24; _STAGE_INDEX=0
  _clear
  printf '\n%s%s  Move the repository to the 860 drive: cut-over%s\n' "$BOLD" "$BLUE" "$RESET"
  say "Start this only when the coordinator has said no agent is working in any worktree."
  say "Phases: pre-window checks, then the window (freeze, final pass, verification, swap, validation, release)."
  [[ "$DRY_RUN" == "1" ]] && warn "DRY RUN: steps are displayed, never executed or recorded"
  if [[ "$DRY_RUN" != "1" ]]; then
    for item in p4c-first p4d-external-first p4e-sizes; do
      phase_done prepare "$item" || { echo "Prepare step $item is not recorded as done. Run  $SELF prepare  first."; REPORTED=1; exit 65; }
    done
  fi
  pause "Press Enter to start"
  sudo_login
  local final_args="--main=$REPO --snapshots=$SNAPSHOTS --received=$RECEIVED --final=$FINAL --state=$MOVE_STATE --inventory=$WIZ/inventory-final.txt --inventory-main=$INVENTORY_MAIN --deadline-seconds=@DEADLINE@ --min-free-gib=$MIN_FREE_GIB"
  local print_args="--main=$REPO --snapshots=$SNAPSHOTS --received=$RECEIVED --final=$FINAL --state=$MOVE_STATE --inventory=$WIZ/inventory-final.txt --inventory-main=$INVENTORY_MAIN --deadline-seconds=$TRANSFER_DEADLINE --min-free-gib=$MIN_FREE_GIB"
  local user_run="runuser -u $USER_NAME -- env HOME=$HOME_DIR"

  STEP_SAYS="Pre-window checks, nothing changes: the checkout is a real writable folder, the 860 is mounted, and no half-done cut-over left objects that would collide."
  STEP_CMD="test -d $REPO && test ! -L $REPO
test \"\$(btrfs property get -ts $REPO ro)\" = ro=false
mountpoint --quiet $DRIVE
test ! -e $FINAL
test -z \"\$(find $SNAPSHOTS $RECEIVED -maxdepth 1 -name 'f[0-9]*' -print)\"
echo checks passed"
  STEP_CHECK="grep --fixed-strings 'checks passed' \"\$OUTPUT_FILE\""; STEP_CHECK_TEXT="all checks passed"
  STEP_ROLLBACK="read-only. A leftover from an aborted attempt (f### snapshots, received copies or $FINAL) must be deleted by you first: $SELF thaw prints the list"
  run_step c00-checks "Pre-window checks"

  STEP_SAYS="Table of every worktree before the freeze, timed. Any row with an unfinished merge, rebase, cherry-pick, revert, bisect or a held index.lock must be settled by its owner before the freeze (plan, section Quiesce and freeze). The time measured here feeds the window maximum."
  STEP_CMD="systemd-run $USER_SCOPE timeout --kill-after=$KILL_GRACE $SCAN_TIMEOUT $NODE $SCAN_SCRIPT $REPO $WIZ/pre-freeze.tsv $SCAN_PER_WORKTREE_SECONDS
/usr/bin/git --no-optional-locks -C $REPO worktree list --porcelain > $WIZ/porcelain-start.txt"
  STEP_CHECK="awk -F'\\t' 'NR > 1 && (\$2 != \"ok\" || \$5 != \"\" || \$6 == \"true\") { print \"settle first: \" \$1 \" (\" \$2 \" \" \$5 \" lock=\" \$6 \")\"; bad = 1 } END { exit bad }' $WIZ/pre-freeze.tsv"
  STEP_CHECK_TEXT="no worktree is missing, failing, mid-operation or holding index.lock"
  STEP_ROLLBACK="read-only"
  STEP_TIMER="scan-seconds"
  run_step c01-pre-freeze-table "Table before the freeze"

  STEP_SAYS="The stated maximum of the cut-over window, from numbers this wizard measured: first pass + a content-check allowance (one more first-pass duration, the script author's choice) + 2 x scan + 2 x footprint. You may shorten it with MOVE_WINDOW_MAX_SECONDS, never lengthen it."
  STEP_CMD="bash $SELF __window-maximum"
  STEP_CHECK="test -s $WIZ/window-max-seconds"; STEP_CHECK_TEXT="the maximum is recorded"
  STEP_ROLLBACK="nothing started; the clock starts only at the step that stops the units"
  run_step c02-window-maximum "Window maximum"

  STEP_SAYS="Holder scan before the freeze: any process whose working folder or open file lies in the repository, in $EXTERNAL_WORKTREES, or in a worktree elsewhere. Run as root so rootless containers are seen. Nothing is signalled."
  STEP_CMD="$(holder_scan_command holders-before)"
  STEP_OK_CODES="0 1"
  STEP_CHECK="echo \"scanner messages: \$(wc --lines < $WIZ/holders-before.err)\"; test ! -s $WIZ/holders-before.txt || { echo 'holders found:'; cat $WIZ/holders-before.txt; exit 1; }"
  STEP_CHECK_TEXT="no holder (find may exit 1 for processes that vanish while scanning; $WIZ/holders-before.err keeps its messages)"
  STEP_ROLLBACK="nothing changed. Ask each session to finish, then run $SELF cutover again"
  run_step c03-holders-before "Holder scan before the freeze"

  STEP_SAYS="Wrapper state: no commit in progress (busy/) and no planned push (push-retries/) for any commit service instance; the pending transactions in .git are listed (they move unchanged with .git)."
  STEP_CMD="/usr/bin/find $CLI_GIT_STATE \\( -path '*/busy/*' -o -path '*/push-retries/*' \\) -type f -print > $WIZ/wrapper-busy.txt
compgen -G '$REPO/.git/cli-git-transactions/*.pending' || echo 'no pending transactions'"
  STEP_CHECK="test ! -s $WIZ/wrapper-busy.txt || { cat $WIZ/wrapper-busy.txt; echo 'push the branches of these plans by hand, then run again'; exit 1; }"
  STEP_CHECK_TEXT="busy/ and push-retries/ are empty everywhere"
  STEP_ROLLBACK="read-only"
  run_step c04-wrapper-state "Wrapper state"

  STEP_SAYS="R0 again, because worktrees come and go since the first inventory. The copy script's print mode then reconciles it with Git and prints the freeze lines it will run."
  STEP_CMD="sudo btrfs subvolume list /var/home > $WIZ/inventory-final.txt
$NODE $MOVE_SCRIPT --pass=final --freeze $print_args > $WIZ/final-pass-print.txt
grep '^btrfs property set -ts ' $WIZ/final-pass-print.txt > $WIZ/freeze-commands.txt
sed 's/ ro true\$/ ro false/' $WIZ/freeze-commands.txt > $WIZ/thaw-commands.txt
echo \"subvolumes to freeze: \$(wc --lines < $WIZ/freeze-commands.txt)\""
  STEP_CHECK="grep --extended-regexp 'inventory agrees' \"\$OUTPUT_FILE\" && test \"\$(wc --lines < $WIZ/freeze-commands.txt)\" -ge 1 && test \"\$(wc --lines < $WIZ/freeze-commands.txt)\" = \"\$(grep --count 'btrfs send' $WIZ/final-pass-print.txt)\""
  STEP_CHECK_TEXT="the inventory agrees with Git and one freeze line exists per subvolume to send"
  STEP_ROLLBACK="read-only. On a refusal give the named subvolumes a written disposition and start the cut-over again"
  run_step c05-fresh-inventory "Fresh inventory and freeze list"

  STEP_SAYS="THE WINDOW STARTS AT THIS STEP. It stops the repository's user units, so commits fail from here. Maximum: see the window maximum step. Freeze, final pass, verification and swap must finish inside it or the wizard stops and tells you to thaw."
  STEP_ASK="Has the coordinator said no agent is working in any worktree, and do you accept commits being refused until the window ends?"
  STEP_WINDOW_START="yes"
  STEP_CMD="systemctl --user list-units --plain --no-legend --all 'cli-git@*' | awk '{ print \$1 }' > $WIZ/stopped-units.txt
systemctl --user is-active --quiet claude-cpu-watch.service && echo claude-cpu-watch.service >> $WIZ/stopped-units.txt || true
xargs --arguments-file=$WIZ/stopped-units.txt --no-run-if-empty systemctl --user stop"
  STEP_CHECK="test \"\$(systemctl --user list-units --plain --no-legend --state=active 'cli-git@*' | wc --lines)\" = 0 && ! systemctl --user is-active --quiet claude-cpu-watch.service"
  STEP_CHECK_TEXT="no commit service is active and claude-cpu-watch.service is stopped"
  STEP_ROLLBACK="$SELF thaw (restarts claude-cpu-watch.service; commit services start again on the next commit)"
  run_step c06-stop-units "Window starts: stop the user units"

  STEP_WINDOW="yes"
  STEP_SAYS="FREEZE: the property ro=true on the checkout and every nested subvolume (the lines in $WIZ/freeze-commands.txt), then a read-only bind mount over each external worktree. A write through a descriptor opened before this still succeeds (measured in the plan), which is why the next stage scans again."
  STEP_CMD="sudo bash -euo pipefail $WIZ/freeze-commands.txt
for name in $(ext_names | tr '\n' ' '); do
  grep --fixed-strings --line-regexp --quiet $EXTERNAL_WORKTREES/\$name $WIZ/ext-binds.txt 2>/dev/null || echo $EXTERNAL_WORKTREES/\$name >> $WIZ/ext-binds.txt
  mountpoint --quiet $EXTERNAL_WORKTREES/\$name || { sudo mount --bind $EXTERNAL_WORKTREES/\$name $EXTERNAL_WORKTREES/\$name && sudo mount -o remount,ro,bind $EXTERNAL_WORKTREES/\$name; }
done"
  STEP_CHECK="bad=0; while read -r p; do v=\$(sudo btrfs property get -ts \"\$p\" ro); [ \"\$v\" = ro=true ] || { echo \"\$p: \$v\"; bad=1; }; done < <(awk '{ print \$5 }' $WIZ/freeze-commands.txt); while read -r p; do findmnt --noheadings --output OPTIONS --mountpoint \"\$p\" | grep --quiet -E '(^|,)ro(,|\$)' || { echo \"\$p not read-only\"; bad=1; }; done < $WIZ/ext-binds.txt; exit \$bad"
  STEP_CHECK_TEXT="every listed subvolume reads ro=true and every external folder is a read-only mount"
  STEP_ROLLBACK="$SELF thaw (ro=false on every frozen subvolume, umount of the external binds, units restarted)"
  run_step c07-freeze "Freeze"

  STEP_WINDOW="yes"
  STEP_SAYS="Holder scan after the freeze. A holder now has a descriptor open that the freeze cannot stop: thaw and report it."
  STEP_CMD="$(holder_scan_command holders-frozen)"
  STEP_OK_CODES="0 1"
  STEP_CHECK="echo \"scanner messages: \$(wc --lines < $WIZ/holders-frozen.err)\"; test ! -s $WIZ/holders-frozen.txt || { echo 'holders found:'; cat $WIZ/holders-frozen.txt; echo \"run: $SELF thaw\"; exit 1; }"
  STEP_CHECK_TEXT="no holder"
  STEP_ROLLBACK="$SELF thaw"
  run_step c08-holders-frozen "Holder scan after the freeze"

  STEP_WINDOW="yes"
  STEP_SAYS="Baseline of the frozen tree: the table of every worktree (registration, HEAD, index hash, change counts, unfinished operations) and the hash of all refs. Taken after the freeze, because values taken earlier legitimately differ."
  STEP_CMD="systemd-run $USER_SCOPE timeout --kill-after=$KILL_GRACE $SCAN_TIMEOUT $NODE $SCAN_SCRIPT $REPO $WIZ/baseline-frozen.tsv $SCAN_PER_WORKTREE_SECONDS
/usr/bin/git --no-optional-locks -C $REPO for-each-ref | sha256sum | cut --delimiter=' ' --fields=1 > $WIZ/frozen-refs.sha
/usr/bin/git --no-optional-locks -C $REPO worktree list --porcelain > $WIZ/porcelain-frozen.txt"
  STEP_CHECK="awk -F'\\t' 'NR > 1 && (\$2 != \"ok\" || \$5 != \"\" || \$6 == \"true\") { print \"unsettled: \" \$1; bad = 1 } END { exit bad }' $WIZ/baseline-frozen.tsv && test -s $WIZ/frozen-refs.sha"
  STEP_CHECK_TEXT="no unsettled row and the refs hash exists"
  STEP_ROLLBACK="$SELF thaw"
  run_step c09-baseline "Baseline of the frozen tree"

  STEP_WINDOW="yes"
  STEP_SAYS="FINAL PASS: new read-only snapshots, incremental sends against the first-pass copies, and each copy placed as a writable subvolume at its final path. The tree is frozen, so no freeze flag is passed. Deadline per transfer: the smaller of $TRANSFER_DEADLINE s and what remains of the window."
  STEP_CMD="sudo $NODE $MOVE_SCRIPT --run --pass=final $final_args"
  STEP_CHECK="grep --fixed-strings 'pass final finished' \"\$OUTPUT_FILE\" && test \"\$(ls $MOVE_STATE | grep --count '^f[0-9]*\\.placed\\.json\$')\" = \"\$(ls $MOVE_STATE | grep --count '^f[0-9]*\\.snapshot\\.json\$')\" && test \"\$(btrfs property get -ts $FINAL ro)\" = ro=false"
  STEP_CHECK_TEXT="'pass final finished', a placed record for every final snapshot, and the placed checkout is writable"
  STEP_ROLLBACK="$SELF thaw. The old tree is untouched; the partial 860 copy stays for you to delete (thaw prints the list)"
  run_step c10-final-pass "Final pass"

  STEP_WINDOW="yes"
  STEP_SAYS="External worktrees, pass two: the same rsync again, now from the read-only mounts. It does not delete from the copy; the comparison later reports anything extra."
  STEP_CMD="for name in $(ext_names | tr '\n' ' '); do
  sudo systemd-run $ROOT_SCOPE rsync --archive --hard-links --acls --xattrs --numeric-ids --one-file-system $EXTERNAL_WORKTREES/\$name/ $EXTERNAL_FINAL/\$name/
done"
  STEP_CHECK="true"; STEP_CHECK_TEXT="the loop exited 0 (content is compared in the external-worktrees verification stage)"
  STEP_ROLLBACK="$SELF thaw"
  run_step c11-external-final "External worktrees: pass two"

  STEP_WINDOW="yes"
  STEP_SAYS="Verification 1 to 3, in a private mount namespace that binds the copy over the real paths, so every .git file and gitdir file resolves into the copy. Git and the scan run as you. 1: git fsck --full. 2: the table equals the frozen baseline byte for byte. 3: the refs hash equals the frozen one."
  STEP_CMD="sudo unshare --mount --propagation private bash -euo pipefail -c \"
  mount --bind $FINAL $REPO
  mount --bind $EXTERNAL_FINAL $EXTERNAL_WORKTREES
  $user_run /usr/bin/git --no-optional-locks -C $REPO fsck --full
  $user_run $NODE $SCAN_SCRIPT $REPO $WIZ/staged.tsv $SCAN_PER_WORKTREE_SECONDS
  $user_run /usr/bin/git --no-optional-locks -C $REPO for-each-ref | sha256sum | cut --delimiter=' ' --fields=1 > $WIZ/staged-refs.sha
  $user_run /usr/bin/git --no-optional-locks -C $REPO worktree list --porcelain > $WIZ/porcelain-staged.txt
\""
  STEP_CHECK="cmp $WIZ/baseline-frozen.tsv $WIZ/staged.tsv && cmp $WIZ/frozen-refs.sha $WIZ/staged-refs.sha && cmp $WIZ/porcelain-frozen.txt $WIZ/porcelain-staged.txt"
  STEP_CHECK_TEXT="staged table, refs hash and worktree list are byte for byte equal to the frozen ones"
  STEP_ROLLBACK="$SELF thaw (the namespace vanished with the command)"
  run_step c12-verify-staged "Verify 1-3: fsck, table, refs"

  STEP_WINDOW="yes"
  STEP_SAYS="Choose the subvolumes whose content is compared byte by byte: the checkout, every worktree with a non-clean baseline row, and the six largest and six smallest by the size table. The plan says the rest 'if time allows'; this wizard checks the rest by file count in the count stage."
  STEP_CMD="STATE_DIR_FOR_SELECT=$MOVE_STATE bash $SELF __select-verify"
  STEP_CHECK="test -s $WIZ/verify-set.tsv"; STEP_CHECK_TEXT="the selection is not empty"
  STEP_ROLLBACK="read-only"
  run_step c13a-select "Verify 4: choose subvolumes"

  STEP_WINDOW="yes"
  STEP_SAYS="Verification 4: rsync --checksum --dry-run of each chosen source snapshot against its placed copy must print nothing (--one-file-system keeps the comparison at the subvolume boundary)."
  STEP_CMD="while IFS=\$'\\t' read -r name path; do
  target=\$(sed -n 's/.*\"target\":\"\\([^\"]*\\)\".*/\\1/p' $MOVE_STATE/\$name.placed.json)
  sudo rsync --archive --checksum --dry-run --itemize-changes --delete --one-file-system --omit-dir-times $SNAPSHOTS/\$name/ \$target/
done < $WIZ/verify-set.tsv > $WIZ/rsync-compare.txt"
  STEP_CHECK="test ! -s $WIZ/rsync-compare.txt || { head --lines=20 $WIZ/rsync-compare.txt; exit 1; }"
  STEP_CHECK_TEXT="rsync printed nothing for every chosen subvolume"
  STEP_ROLLBACK="$SELF thaw"
  run_step c13b-rsync "Verify 4: content compare"

  STEP_WINDOW="yes"
  STEP_SAYS="Verification 5: sharing kept. The copy's footprint (exclusive plus set shared) must not exceed ${SHARING_LIMIT_PERCENT} percent of the frozen source's, the plan's quarter margin. A larger copy means extents were written again and the swap does not happen."
  STEP_CMD="sudo systemd-run $ROOT_SCOPE timeout --kill-after=$KILL_GRACE $MEASURE_TIMEOUT btrfs filesystem du --summarize --raw $FINAL | tee $WIZ/final-du.txt
sudo systemd-run $ROOT_SCOPE timeout --kill-after=$KILL_GRACE $MEASURE_TIMEOUT btrfs filesystem du --summarize --raw $REPO | tee $WIZ/source-du.txt"
  STEP_CHECK="test \$(( \$(awk 'END { print \$2 + \$3 }' $WIZ/final-du.txt) * 100 )) -le \$(( \$(awk 'END { print \$2 + \$3 }' $WIZ/source-du.txt) * $SHARING_LIMIT_PERCENT ))"
  STEP_CHECK_TEXT="copy footprint within ${SHARING_LIMIT_PERCENT} percent of the source"
  STEP_ROLLBACK="$SELF thaw"
  run_step c14-sharing "Verify 5: sharing kept"

  STEP_WINDOW="yes"
  STEP_SAYS="Verification 6: file counts equal for every subvolume (source snapshot against placed copy, as root, within each subvolume)."
  STEP_CMD="while IFS=\$'\\t' read -r name path; do
  target=\$(sed -n 's/.*\"target\":\"\\([^\"]*\\)\".*/\\1/p' $MOVE_STATE/\$name.placed.json)
  echo \"\$name \$(sudo find $SNAPSHOTS/\$name -xdev -type f | wc --lines) \$(sudo find \$target -xdev -type f | wc --lines)\"
done < $WIZ/final-map.tsv | tee $WIZ/file-counts.txt"
  STEP_CHECK="awk '\$2 != \$3 { print \"differs: \" \$0; bad = 1 } END { exit bad }' $WIZ/file-counts.txt"
  STEP_CHECK_TEXT="every subvolume has equal counts on both sides"
  STEP_ROLLBACK="$SELF thaw"
  run_step c15-counts "Verify 6: file counts"

  STEP_WINDOW="yes"
  STEP_SAYS="Verification 7: root-owned files survived (the plan found 126 root-owned log files that an unprivileged copy cannot read). Counted on the frozen source and on the copy."
  STEP_CMD="echo \"source \$(sudo find $REPO -user root -name '*.log.jsonl' | wc --lines)\"
echo \"copy \$(sudo find $FINAL -user root -name '*.log.jsonl' | wc --lines)\""
  STEP_CHECK="test \"\$(grep '^source ' \"\$OUTPUT_FILE\" | cut --delimiter=' ' --fields=2)\" = \"\$(grep '^copy ' \"\$OUTPUT_FILE\" | cut --delimiter=' ' --fields=2)\""
  STEP_CHECK_TEXT="equal counts (zero on both sides means none exist now; the plan's 126 may be gone)"
  STEP_ROLLBACK="$SELF thaw"
  run_step c16-root-owned "Verify 7: root-owned files"

  STEP_WINDOW="yes"
  STEP_SAYS="Verification 8: each external worktree's read-only source against its copy prints nothing, including nothing extra in the copy (--delete in dry-run only reports)."
  STEP_CMD="for name in $(ext_names | tr '\n' ' '); do
  sudo rsync --archive --checksum --dry-run --itemize-changes --delete --one-file-system --omit-dir-times $EXTERNAL_WORKTREES/\$name/ $EXTERNAL_FINAL/\$name/
done > $WIZ/external-compare.txt"
  STEP_CHECK="test ! -s $WIZ/external-compare.txt || { head --lines=20 $WIZ/external-compare.txt; exit 1; }"
  STEP_CHECK_TEXT="rsync printed nothing for every external folder"
  STEP_ROLLBACK="$SELF thaw. An extra file in a copy means a file was deleted in the source after pass one; remove it from the copy yourself, then run this stage again"
  run_step c17-externals "Verify 8: external worktrees"

  STEP_WINDOW="yes"
  STEP_SAYS="MOUNTPOINT GUARD (plan R1 and R2) before the swap: in a private namespace, bind the NVMe /var, require that the hidden /var/mnt/encrypted folder holds no entries, then make it root-owned, mode 0755 and immutable. Without it a program that creates the resolved path while the 860 is away writes to the NVMe. It stops if the alias is not the NVMe or the folder holds entries."
  STEP_CMD="sudo unshare --mount --propagation private bash -euo pipefail -c '
  alias_dir=\$(mktemp --directory /run/underlying-var.XXXXXX)
  mount --bind /var \"\$alias_dir\"
  hidden=\"\$alias_dir${DRIVE#/var}\"
  [ \"\$(findmnt --noheadings --output UUID --target \"\$alias_dir\")\" = \"\$(findmnt --noheadings --output UUID --target /var)\" ]
  [ \"\$(findmnt --noheadings --output UUID --target \"\$alias_dir\")\" != \"\$(findmnt --noheadings --output UUID --target $DRIVE)\" ]
  stat --format=\"%U:%G %a %n\" \"\$hidden\"
  lsattr -d \"\$hidden\"
  entries=\$(ls -A \"\$hidden\" | wc --lines)
  echo \"entries under the hidden mountpoint: \$entries\"
  [ \"\$entries\" -eq 0 ]
  chown root:root \"\$hidden\"
  chmod 0755 \"\$hidden\"
  chattr +i \"\$hidden\"
  echo \"after guard: \$(lsattr -d \"\$hidden\")\"
  umount \"\$alias_dir\"
  rmdir \"\$alias_dir\"
'
echo \"mounted drive: \$(lsattr -d $DRIVE)\""
  STEP_CHECK="grep --extended-regexp '^after guard: .{4}i' \"\$OUTPUT_FILE\" && ! grep --extended-regexp '^mounted drive: .{4}i' \"\$OUTPUT_FILE\""
  STEP_CHECK_TEXT="the hidden folder shows the i flag and the mounted 860 does not"
  STEP_ROLLBACK="the guard is harmless to keep. To undo: the same namespace pattern with chattr -i on the hidden folder. If entries were found, read and move them yourself, then run this stage again"
  run_step c18-guard "Mountpoint guard"

  local stamp
  if [[ -s "$WIZ/swap-timestamp" ]]; then stamp="$(<"$WIZ/swap-timestamp")"; else stamp="$(date +%Y%m%dT%H%M%S%z)"; [[ "$DRY_RUN" == "1" ]] || printf '%s\n' "$stamp" > "$WIZ/swap-timestamp"; fi
  STEP_WINDOW="yes"
  STEP_SAYS="SWAP: rename the old checkout and the old external-worktrees folder aside (renames, no copy, no delete), then point the old paths at the copies with symbolic links. The old trees stay frozen and read-only as cold storage."
  STEP_CMD="test ! -e $REPO.nvme-before-860-$stamp && test ! -e $EXTERNAL_WORKTREES.nvme-before-860-$stamp
test -d $FINAL/.git && test -d $EXTERNAL_FINAL
mv --no-clobber --no-target-directory $REPO $REPO.nvme-before-860-$stamp
ln --symbolic $FINAL $REPO
mv --no-clobber --no-target-directory $EXTERNAL_WORKTREES $EXTERNAL_WORKTREES.nvme-before-860-$stamp
ln --symbolic $EXTERNAL_FINAL $EXTERNAL_WORKTREES
ls -ld $REPO $EXTERNAL_WORKTREES"
  STEP_CHECK="test -L $REPO && test \"\$(readlink $REPO)\" = $FINAL && test -L $EXTERNAL_WORKTREES && test \"\$(readlink $EXTERNAL_WORKTREES)\" = $EXTERNAL_FINAL && test -d $REPO/.git && test -d $REPO.nvme-before-860-$stamp"
  STEP_CHECK_TEXT="both old paths are links to the 860 copies, the checkout's .git resolves through the link, the old tree sits beside it"
  STEP_ROLLBACK="$SELF rollback (fast path, valid only until the release stage)"
  run_step c19-swap "Swap the old paths to links"

  STEP_WINDOW="yes"
  STEP_SAYS="Verification 9: the same fsck, table and worktree list, now through the real link."
  STEP_CMD="/usr/bin/git --no-optional-locks -C $REPO fsck --full
systemd-run $USER_SCOPE timeout --kill-after=$KILL_GRACE $SCAN_TIMEOUT $NODE $SCAN_SCRIPT $REPO $WIZ/through-link.tsv $SCAN_PER_WORKTREE_SECONDS
/usr/bin/git --no-optional-locks -C $REPO worktree list --porcelain > $WIZ/porcelain-through-link.txt"
  STEP_CHECK="cmp $WIZ/baseline-frozen.tsv $WIZ/through-link.tsv && cmp $WIZ/porcelain-frozen.txt $WIZ/porcelain-through-link.txt"
  STEP_CHECK_TEXT="table and worktree list through the link equal the frozen baseline"
  STEP_ROLLBACK="$SELF rollback"
  run_step c20-through-link "Verify 9: through the link"

  STEP_WINDOW="yes"
  STEP_SAYS="RELEASE: start the stopped commit sockets and claude-cpu-watch.service again and close the window. After this the fast rollback no longer applies (writes will reach the 860 tree); a later rollback is the full reverse migration in the plan, section Rollback, which this script does not run."
  STEP_ASK="Release now? Last chance for the fast rollback."
  STEP_CMD="{ grep '\\.socket\$' $WIZ/stopped-units.txt || true; } | xargs --no-run-if-empty systemctl --user start || echo 'WARNING: a commit socket did not restart; list-units cli-git@* shows which'
if grep --fixed-strings --line-regexp --quiet claude-cpu-watch.service $WIZ/stopped-units.txt; then systemctl --user start claude-cpu-watch.service; fi
date +%s > $WIZ/window-end
echo \"window length: \$(( \$(cat $WIZ/window-end) - \$(cat $WIZ/window-start) )) s\""
  STEP_CHECK="! grep --fixed-strings --line-regexp --quiet claude-cpu-watch.service $WIZ/stopped-units.txt || systemctl --user is-active --quiet claude-cpu-watch.service"; STEP_CHECK_TEXT="claude-cpu-watch.service is active again (if the cut-over stopped it)"
  STEP_ROLLBACK="none after this stage; see the plan, section Rollback, full path"
  run_step c21-release "Release"

  _clear
  printf '\n%s%s  The repository is now at %s through a link.%s\n\n' "$BOLD" "$GREEN" "$FINAL" "$RESET"
  say "Still yours to do (not run by this script):"
  note "  - owner checks from the plan, Cut-over phase 5: one test commit in a throwaway worktree (the wrapper may push it), mise trust --all then mise trust --show, one created container, a fresh worktree's pnpm install then find node_modules -xtype l"
  note "  - the identity file and repository-link-check of the plan's W1 are not built yet, so nothing was recorded for them"
  note "  - one probe session to see which project key the harness writes, then the harness migration, with no session running"
  note "  - old trees to remove later, by you, after comparing with the baselines: $REPO.nvme-before-860-$stamp and $EXTERNAL_WORKTREES.nvme-before-860-$stamp"
  note "  - source snapshots in $SNAPSHOTS and received first-pass copies in $RECEIVED, once the validation window has closed"
  log_line "cutover finished"
}

thaw_steps() {
  STEP_NO_MARK="yes"
  STEP_SAYS="Thaw: ro=false on every subvolume this wizard froze (the lines in $WIZ/thaw-commands.txt). Idempotent."
  STEP_CMD="sudo bash -euo pipefail $WIZ/thaw-commands.txt"
  STEP_CHECK="bad=0; while read -r p; do v=\$(sudo btrfs property get -ts \"\$p\" ro); [ \"\$v\" = ro=false ] || { echo \"\$p: \$v\"; bad=1; }; done < <(awk '{ print \$5 }' $WIZ/thaw-commands.txt); exit \$bad"
  STEP_CHECK_TEXT="every listed subvolume reads ro=false"
  STEP_ROLLBACK="freeze again by running the cut-over"
  run_step t1-thaw-subvolumes "Thaw the subvolumes"
  STEP_NO_MARK="yes"
  STEP_SAYS="Unmount the read-only binds over the external worktrees (only those still mounted)."
  STEP_CMD="touch $WIZ/ext-binds.txt
while read -r p; do if mountpoint --quiet \"\$p\"; then sudo umount \"\$p\"; fi; done < $WIZ/ext-binds.txt"
  STEP_CHECK="while read -r p; do ! mountpoint --quiet \"\$p\" || { echo \"\$p still mounted\"; exit 1; }; done < $WIZ/ext-binds.txt"
  STEP_CHECK_TEXT="no external folder is still a mount"
  STEP_ROLLBACK="freeze again by running the cut-over"
  run_step t2-umount-binds "Unmount external binds"
  STEP_NO_MARK="yes"
  STEP_SAYS="Start again what the cut-over stopped: the commit sockets (restarting them is harmless; whether the wrapper would start them itself was not verified) and claude-cpu-watch.service."
  STEP_CMD="touch $WIZ/stopped-units.txt
{ grep '\\.socket\$' $WIZ/stopped-units.txt || true; } | xargs --no-run-if-empty systemctl --user start || echo 'WARNING: a commit socket did not restart; list-units cli-git@* shows which'
if grep --fixed-strings --line-regexp --quiet claude-cpu-watch.service $WIZ/stopped-units.txt; then systemctl --user start claude-cpu-watch.service; else echo 'claude-cpu-watch.service was not stopped by the cut-over'; fi"
  STEP_CHECK="true"; STEP_CHECK_TEXT="the command exited 0"
  STEP_ROLLBACK="systemctl --user stop claude-cpu-watch.service"
  run_step t3-restart-units "Restart the stopped unit"
}

thaw_aftermath() {
  local stamp; stamp="$(date +%Y%m%dT%H%M%S%z)"
  if [[ "$DRY_RUN" == "1" ]]; then note "dry run: the cut-over progress and the window clock would be renamed aside here"; return 0; fi
  if [[ -d "$WIZ/done/cutover" ]]; then mv --no-target-directory "$WIZ/done/cutover" "$WIZ/done/cutover.aborted-$stamp"; fi
  if [[ -e "$WIZ/window-start" ]]; then mv "$WIZ/window-start" "$WIZ/window-start.aborted-$stamp"; fi
  if [[ -e "$WIZ/swap-timestamp" ]]; then mv "$WIZ/swap-timestamp" "$WIZ/swap-timestamp.aborted-$stamp"; fi
  warn "If a timeout stopped the final pass, its systemd scope may still be running until its own deadline: wait for 'systemctl list-units run-*.scope' to show no btrfs send before deleting a partial receive."
  say "Nothing was deleted. The cut-over progress and window clock were renamed aside (suffix .aborted-$stamp)."
  say "Before another cut-over attempt, remove the leftovers of this one yourself, because the copy script refuses to reuse them:"
  note "  snapshots on the NVMe:   $(ls "$SNAPSHOTS" 2>/dev/null | grep '^f[0-9]' | tr '\n' ' ')"
  note "  received copies on 860:  $(ls "$RECEIVED" 2>/dev/null | grep '^f[0-9]' | tr '\n' ' ')"
  note "  placed copy:             $FINAL (nested subvolumes first, then the root: sudo btrfs subvolume delete)"
  note "  state records:           move $MOVE_STATE/f*.json aside"
}

thaw_main() {
  PHASE=thaw; TOTAL_STAGES=4; _STAGE_INDEX=0
  _clear
  printf '\n%s%s  Thaw: undo the freeze (swap not done)%s\n' "$BOLD" "$BLUE" "$RESET"
  if [[ -L "$REPO" ]]; then echo "$REPO is already a link: the swap happened. Use  $SELF rollback  instead."; REPORTED=1; exit 65; fi
  need_file "$WIZ/thaw-commands.txt" "written by the cut-over stage c05-fresh-inventory"
  pause "Press Enter to start"
  sudo_login
  thaw_steps
  thaw_aftermath
}

rollback_main() {
  PHASE=rollback; TOTAL_STAGES=6; _STAGE_INDEX=0
  _clear
  printf '\n%s%s  Fast rollback after the swap%s\n' "$BOLD" "$BLUE" "$RESET"
  [[ -s "$WIZ/swap-timestamp" ]] || { echo "No swap was recorded. Use  $SELF thaw  instead."; REPORTED=1; exit 65; }
  [[ -e "$WIZ/done/cutover/c19-swap" ]] || { echo "The swap stage did not complete. Use  $SELF thaw  instead."; REPORTED=1; exit 65; }
  if [[ -e "$WIZ/done/cutover/c21-release" ]]; then
    echo "The release stage ran: writes may have reached the 860 tree. The fast rollback no longer applies."
    echo "Use the full reverse migration in doc/planning/repository-on-the-860-drive.md, section Rollback."
    REPORTED=1; exit 65
  fi
  local stamp; stamp="$(<"$WIZ/swap-timestamp")"
  pause "Press Enter to start"
  sudo_login
  STEP_NO_MARK="yes"
  STEP_SAYS="The old trees must still be frozen (nothing wrote to them since the freeze)."
  STEP_CMD="while read -r p; do echo \"\$p: \$(btrfs property get -ts \"$REPO.nvme-before-860-$stamp\${p#$REPO}\" ro)\"; done < <(awk '{ print \$5 }' $WIZ/freeze-commands.txt)"
  STEP_CHECK="! grep --fixed-strings 'ro=false' \"\$OUTPUT_FILE\""; STEP_CHECK_TEXT="every old subvolume still reads ro=true"
  STEP_ROLLBACK="read-only"
  run_step r1-old-still-frozen "Old tree still frozen"
  STEP_NO_MARK="yes"
  STEP_SAYS="Put the links aside (renamed, not deleted) and the old folders back. Refuses if either old path is occupied by something else."
  STEP_CMD="test -L $REPO && test -L $EXTERNAL_WORKTREES
test ! -e $REPO.link-rolled-back-$stamp && test ! -e $EXTERNAL_WORKTREES.link-rolled-back-$stamp
mv --no-clobber --no-target-directory $REPO $REPO.link-rolled-back-$stamp
mv --no-clobber --no-target-directory $REPO.nvme-before-860-$stamp $REPO
mv --no-clobber --no-target-directory $EXTERNAL_WORKTREES $EXTERNAL_WORKTREES.link-rolled-back-$stamp
mv --no-clobber --no-target-directory $EXTERNAL_WORKTREES.nvme-before-860-$stamp $EXTERNAL_WORKTREES"
  STEP_CHECK="test -d $REPO && test ! -L $REPO && test -d $EXTERNAL_WORKTREES && test ! -L $EXTERNAL_WORKTREES"
  STEP_CHECK_TEXT="both old paths are real folders again"
  STEP_ROLLBACK="the links are beside them with the suffix .link-rolled-back-$stamp"
  run_step r2-restore-names "Put the old folders back"
  thaw_steps
  _clear
  printf '\n%s%s  Rolled back.%s\n' "$BOLD" "$GREEN" "$RESET"
  say "Nothing was deleted. The 860 copy remains for you to delete or reuse; the links are at $REPO.link-rolled-back-$stamp."
  thaw_aftermath
}

status_main() {
  PHASE=status
  say "State folder: $WIZ"
  local dir
  for dir in prepare cutover thaw rollback; do
    PHASE="$dir"; list_progress
  done
  if [[ -s "$WIZ/window-max-seconds" ]]; then note "window maximum: $(<"$WIZ/window-max-seconds") s"; fi
  if window_running; then note "window running; remaining $(window_remaining) s"; fi
  if [[ -s "$WIZ/window-end" ]]; then note "window ended at epoch $(<"$WIZ/window-end")"; fi
}

usage() {
  cat <<EOF
Usage: $(basename "$0") prepare | cutover | thaw | rollback | status
  prepare   sudo login, fixture test, inventory, space check, first pass; stops before any cut-over
  cutover   the window: freeze, final pass, verification, swap, validation, release (has a stated maximum)
  thaw      undo the freeze while the swap has not happened
  rollback  fast rollback after the swap, valid until the release stage
  status    what has completed
Set WIZARD_DRY_RUN=1 to show every step without running or recording anything.
EOF
}

main() {
  local command="${1:-}"
  case "$command" in
    __preflight) REPORTED=1; internal_preflight; return ;;
    __window-maximum) REPORTED=1; internal_window_maximum; return ;;
    __select-verify) REPORTED=1; internal_select_verify; return ;;
  esac
  [[ "$DRY_RUN" == "1" ]] || startup_checks

  shift || true
  for argument in "$@"; do
    case "$argument" in --redo=*) REDO["${argument#--redo=}"]=1 ;; esac
  done
  case "$command" in
    prepare) prepare_main ;;
    cutover) cutover_main ;;
    thaw) thaw_main ;;
    rollback) rollback_main ;;
    status) status_main ;;
    *) usage; REPORTED=1; exit 64 ;;
  esac
}

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then
  main "$@"
fi
